// The normative ADR-0002 tables (docs/adr/0002-public-key-identity.md).
// testdata/vectors.json is generated by testdata/gen.sh; these tables are the
// specification, and the tests require the two to agree.
var adr0002KeyID = map[string]string{
	"rsa-2048":   "8fb6bad671cfe698393c453357da61b56d757ab8c0f3fb9c87f2849e63131878",
	"ecdsa-p256": "b2b04340cfaee616ec9c2c62d261b208e54bb197498df52e8cadede23ac0ba5e",
	"ed25519":    "a1e9156054e04fac899ae9f275132cdc07a5dbc4ea2c2ad3a1ffc6e0d253681f",
	"ml-dsa-44":  "837832708c5236d951581f1fddf2b79991b3424a0486d16da1ddad0fd69701be",
	"ml-dsa-65":  "b8b62131bfbe84433efb2273d7f5b87f7a22854a2cfd366fc2aead86d837c52d",
	"ml-dsa-87":  "07e57c4f14dbad1267f621ec3777b4e2e6c4fbc4c22fbb87510ff8e0b3c6a642",
}

var adr0002Encoded = map[string]string{
	"rsa-2048-no-null":      "675e4501dfdc6442006534585c91eff10fb1da755f8a2dcbe5c434655423ad34",
	"ecdsa-p256-compressed": "b9fd8f074598636ae25ab3f96311e48bc2c602bd6397aad28c74eb0e7f9bf546",
}

type vectorFile struct {
	Positive []struct {
		Name       string `json:"name"`
		KeyID      string `json:"key_id"`
		CertSHA256 string `json:"cert_sha256"`
		PinSHA256  string `json:"pin_sha256"`
	} `json:"positive"`
	TwoScheme []struct {
		Name             string `json:"name"`
		CanonicalSibling string `json:"canonical_sibling"`
		EncodedSHA256    string `json:"encoded_sha256"`
	} `json:"two_scheme"`
}

func loadVectors(t *testing.T) vectorFile {
	t.Helper()
	var vf vectorFile
	if err := json.Unmarshal(readFile(t, "testdata", "vectors.json"), &vf); err != nil {
		t.Fatalf("vectors.json: %v", err)
	}
	if len(vf.Positive) != len(adr0002KeyID) || len(vf.TwoScheme) != len(adr0002Encoded) {
		t.Fatalf("vectors.json has %d positive / %d two-scheme vectors; ADR-0002 defines %d / %d",
			len(vf.Positive), len(vf.TwoScheme), len(adr0002KeyID), len(adr0002Encoded))
	}
	return vf
}

func readFile(t *testing.T, parts ...string) []byte {
	t.Helper()
	b, err := os.ReadFile(filepath.Join(parts...))
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func readPEM(t *testing.T, parts ...string) *pem.Block {
	t.Helper()
	b, rest := pem.Decode(readFile(t, parts...))
	if b == nil || len(bytes.TrimSpace(rest)) != 0 {
		t.Fatalf("%s: want exactly one PEM block", filepath.Join(parts...))
	}
	return b
}

func keyIDOfSPKI(t *testing.T, what string, spki []byte) string {
	t.Helper()
	id, err := fingerprint.KeyIDFromSPKI(spki)
	if err != nil {
		t.Fatalf("%s: KeyIDFromSPKI: %v", what, err)
	}
	return id.Hex()
}

func keyIDOfPublicKey(t *testing.T, what string, pub crypto.PublicKey) string {
	t.Helper()
	id, err := fingerprint.KeyIDFromPublicKey(pub)
	if err != nil {
		t.Fatalf("%s: KeyIDFromPublicKey(%T): %v", what, pub, err)
	}
	return id.Hex()
}

func parsePrivateKey(t *testing.T, b *pem.Block) crypto.Signer {
	t.Helper()
	var (
		k   any
		err error
	)
	switch b.Type {
	case "RSA PRIVATE KEY":
		k, err = x509.ParsePKCS1PrivateKey(b.Bytes)
	case "EC PRIVATE KEY":
		k, err = x509.ParseECPrivateKey(b.Bytes)
	case "PRIVATE KEY":
		k, err = x509.ParsePKCS8PrivateKey(b.Bytes)
	default:
		t.Fatalf("unexpected PEM type %q", b.Type)
	}
	if err != nil {
		t.Fatalf("parse %s: %v", b.Type, err)
	}
	s, ok := k.(crypto.Signer)
	if !ok {
		t.Fatalf("%T is not a crypto.Signer", k)
	}
	return s
}

// TestKeyIDPositiveVectors proves that x509-spki-sha256 is the same for every
// supported representation of each ADR-0002 key, and equals the ADR table.
func TestKeyIDPositiveVectors(t *testing.T) {
	for _, v := range loadVectors(t).Positive {
		t.Run(v.Name, func(t *testing.T) {
			want, ok := adr0002KeyID[v.Name]
			if !ok {
				t.Fatalf("vector %q is not in ADR-0002", v.Name)
			}
			if v.KeyID != want {
				t.Fatalf("vectors.json key_id %s disagrees with ADR-0002 %s", v.KeyID, want)
			}
			dir := filepath.Join("testdata", "vectors", v.Name)

			spkiDER := readFile(t, dir, "spki.der")
			if got := keyIDOfSPKI(t, "spki.der", spkiDER); got != want {
				t.Errorf("spki.der: got %s want %s", got, want)
			}
			if b := readPEM(t, dir, "spki.pem"); !bytes.Equal(b.Bytes, spkiDER) {
				t.Errorf("spki.pem and spki.der differ")
			}

			canon, err := fingerprint.CanonicalSPKI(spkiDER)
			if err != nil {
				t.Fatalf("CanonicalSPKI: %v", err)
			}
			if !bytes.Equal(canon, spkiDER) {
				t.Errorf("canonical SPKI differs from the canonically encoded input")
			}
			if got := fingerprint.EncodedSPKIFromDER(spkiDER).Hex(); got != want {
				t.Errorf("encoded SPKI of a canonical input: got %s want %s", got, want)
			}

			pub, err := x509.ParsePKIXPublicKey(spkiDER)
			if err != nil {
				t.Fatalf("x509.ParsePKIXPublicKey: %v", err)
			}
			if got := keyIDOfPublicKey(t, "parsed SPKI", pub); got != want {
				t.Errorf("parsed SPKI: got %s want %s", got, want)
			}
			// Drift alarm: the spec, not Go, defines the canonical bytes. If a
			// future Go marshals differently, this fails and the ADR decides.
			marshalled, err := x509.MarshalPKIXPublicKey(pub)
			if err != nil {
				t.Fatalf("x509.MarshalPKIXPublicKey: %v", err)
			}
			if !bytes.Equal(marshalled, canon) {
				t.Errorf("drift: x509.MarshalPKIXPublicKey no longer equals the ADR-0002 canonical SPKI")
			}

			cert, err := x509.ParseCertificate(readPEM(t, dir, "cert.pem").Bytes)
			if err != nil {
				t.Fatalf("certificate: %v", err)
			}
			if got := keyIDOfSPKI(t, "certificate SPKI", cert.RawSubjectPublicKeyInfo); got != want {
				t.Errorf("certificate SPKI: got %s want %s", got, want)
			}
			if got := keyIDOfPublicKey(t, "certificate public key", cert.PublicKey); got != want {
				t.Errorf("certificate public key: got %s want %s", got, want)
			}
			if got := fingerprint.CertFromDER(cert.Raw).Hex(); got != v.CertSHA256 {
				t.Errorf("x509-cert-sha256: got %s want %s (openssl)", got, v.CertSHA256)
			}

			csr, err := x509.ParseCertificateRequest(readPEM(t, dir, "csr.pem").Bytes)
			if err != nil {
				t.Fatalf("CSR: %v", err)
			}
			if got := keyIDOfSPKI(t, "CSR SPKI", csr.RawSubjectPublicKeyInfo); got != want {
				t.Errorf("CSR SPKI: got %s want %s", got, want)
			}
			if got := keyIDOfPublicKey(t, "CSR public key", csr.PublicKey); got != want {
				t.Errorf("CSR public key: got %s want %s", got, want)
			}

			for _, f := range []string{"key.pem", "pkcs8.pem"} {
				signer := parsePrivateKey(t, readPEM(t, dir, f))
				if got := keyIDOfPublicKey(t, f, signer.Public()); got != want {
					t.Errorf("%s: got %s want %s", f, got, want)
				}
			}

			if got := fingerprint.EncodedSPKIFromDER(spkiDER).PinSHA256(); got != v.PinSHA256 {
				t.Errorf("pin-sha256: got %s want %s (openssl)", got, v.PinSHA256)
			}
		})
	}
}

// TestKeyIDTwoSchemeVectors proves that non-canonical encodings of a key join
// its canonical identity while their encoded fingerprint stays distinct.
func TestKeyIDTwoSchemeVectors(t *testing.T) {
	for _, v := range loadVectors(t).TwoScheme {
		t.Run(v.Name, func(t *testing.T) {
			wantEncoded, ok := adr0002Encoded[v.Name]
			if !ok {
				t.Fatalf("vector %q is not in ADR-0002", v.Name)
			}
			if v.EncodedSHA256 != wantEncoded {
				t.Fatalf("vectors.json encoded_sha256 %s disagrees with ADR-0002 %s", v.EncodedSHA256, wantEncoded)
			}
			wantKeyID := adr0002KeyID[v.CanonicalSibling]
			der := readFile(t, "testdata", "vectors", v.Name, "spki.der")

			if got := fingerprint.EncodedSPKIFromDER(der).Hex(); got != wantEncoded {
				t.Errorf("x509-spki-encoded-sha256: got %s want %s", got, wantEncoded)
			}
			if got := keyIDOfSPKI(t, "non-canonical SPKI", der); got != wantKeyID {
				t.Errorf("x509-spki-sha256: got %s want sibling %s", got, wantKeyID)
			}
			if wantEncoded == wantKeyID {
				t.Fatal("a two-scheme vector must have distinct encoded and canonical fingerprints")
			}
			canon, err := fingerprint.CanonicalSPKI(der)
			if err != nil {
				t.Fatal(err)
			}
			if sibling := readFile(t, "testdata", "vectors", v.CanonicalSibling, "spki.der"); !bytes.Equal(canon, sibling) {
				t.Errorf("canonical SPKI is not byte-identical to the canonical sibling")
			}
		})
	}
}

// TestKeyIDUnsupported proves that keys outside ADR-0002 get no key identity,
// and are never given one by substituting their encoded bytes.
func TestKeyIDUnsupported(t *testing.T) {
	files, err := filepath.Glob(filepath.Join("testdata", "unsupported", "*.der"))
	if err != nil || len(files) < 6 {
		t.Fatalf("unsupported fixtures missing (%d found, err %v)", len(files), err)
	}
	for _, f := range files {
		t.Run(filepath.Base(f), func(t *testing.T) {
			der := readFile(t, f)
			if _, err := fingerprint.KeyIDFromSPKI(der); !errors.Is(err, fingerprint.ErrUnsupported) {
				t.Errorf("want ErrUnsupported, got %v", err)
			}
			if _, err := fingerprint.CanonicalSPKI(der); !errors.Is(err, fingerprint.ErrUnsupported) {
				t.Errorf("CanonicalSPKI: want ErrUnsupported, got %v", err)
			}
			if fingerprint.EncodedSPKIFromDER(der).Hex() == "" {
				t.Errorf("the encoded fingerprint must still be observable")
			}
		})
	}

	t.Run("unknown OID", func(t *testing.T) {
		der := buildSPKI(t, asn1.ObjectIdentifier{1, 2, 3, 4}, nil, []byte{1, 2, 3})
		if _, err := fingerprint.KeyIDFromSPKI(der); !errors.Is(err, fingerprint.ErrUnsupported) {
			t.Errorf("want ErrUnsupported, got %v", err)
		}
	})
	t.Run("unsupported Go key type", func(t *testing.T) {
		for _, pub := range []crypto.PublicKey{nil, "not a key", struct{}{}} {
			if _, err := fingerprint.KeyIDFromPublicKey(pub); !errors.Is(err, fingerprint.ErrUnsupported) {
				t.Errorf("%T: want ErrUnsupported, got %v", pub, err)
			}
		}
	})
}

var (
	oidRSA     = asn1.ObjectIdentifier{1, 2, 840, 113549, 1, 1, 1}
	oidEC      = asn1.ObjectIdentifier{1, 2, 840, 10045, 2, 1}
	oidP256    = asn1.ObjectIdentifier{1, 2, 840, 10045, 3, 1, 7}
	oidEd25519 = asn1.ObjectIdentifier{1, 3, 101, 112}
	oidMLDSA65 = asn1.ObjectIdentifier{2, 16, 840, 1, 101, 3, 4, 3, 18}
)

// buildSPKI assembles an SPKI with arbitrary parameters (DER, or nil for
// absent) and key bytes, for malformed and unusual inputs.
func buildSPKI(t *testing.T, oid asn1.ObjectIdentifier, params, key []byte) []byte {
	t.Helper()
	var b cryptobyte.Builder
	b.AddASN1(cbasn1.SEQUENCE, func(b *cryptobyte.Builder) {
		b.AddASN1(cbasn1.SEQUENCE, func(b *cryptobyte.Builder) {
			b.AddASN1ObjectIdentifier(oid)
			if params != nil {
				b.AddBytes(params)
			}
		})
		b.AddASN1BitString(key)
	})
	der, err := b.Bytes()
	if err != nil {
		t.Fatal(err)
	}
	return der
}

func derOf(t *testing.T, v any) []byte {
	t.Helper()
	b, err := asn1.Marshal(v)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

// TestKeyIDMalformed proves that structurally broken SPKIs are rejected as
// malformed — not given an identity, and not confused with "unsupported".
func TestKeyIDMalformed(t *testing.T) {
	p256 := readFile(t, "testdata", "vectors", "ecdsa-p256", "spki.der")
	ed := readFile(t, "testdata", "vectors", "ed25519", "spki.der")
	rsaKey := func(n, e int64) []byte {
		t.Helper()
		type rsaPub struct{ N, E int64 }
		return derOf(t, rsaPub{n, e})
	}
	nullParams := []byte{0x05, 0x00}

	mutate := func(src []byte, f func([]byte)) []byte {
		b := bytes.Clone(src)
		f(b)
		return b
	}

	cases := map[string][]byte{
		"empty":                      nil,
		"not a sequence":             {0x04, 0x00},
		"truncated":                  p256[:len(p256)-1],
		"trailing byte":              append(bytes.Clone(p256), 0x00),
		"non-zero unused bits":       mutate(p256, func(b []byte) { b[25] = 1 }),
		"P-256 point off curve":      mutate(p256, func(b []byte) { b[len(b)-1] ^= 0xff }),
		"P-256 point bad prefix":     mutate(p256, func(b []byte) { b[26] = 0x05 }),
		"P-256 point wrong length":   buildSPKI(t, oidEC, derOf(t, oidP256), bytes.Repeat([]byte{4}, 40)),
		"EC parameters missing":      buildSPKI(t, oidEC, nil, p256[26:]),
		"RSA parameters not NULL":    buildSPKI(t, oidRSA, derOf(t, oidP256), rsaKey(3, 65537)),
		"RSA key not RSAPublicKey":   buildSPKI(t, oidRSA, nullParams, []byte{0x02, 0x01, 0x03}),
		"RSA zero modulus":           buildSPKI(t, oidRSA, nullParams, rsaKey(0, 65537)),
		"RSA negative exponent":      buildSPKI(t, oidRSA, nullParams, rsaKey(3, -3)),
		"Ed25519 key too short":      buildSPKI(t, oidEd25519, nil, ed[12:len(ed)-1]),
		"Ed25519 parameters present": buildSPKI(t, oidEd25519, nullParams, ed[12:]),
		"ML-DSA-65 wrong length":     buildSPKI(t, oidMLDSA65, nil, make([]byte, 1951)),
	}
	for name, der := range cases {
		t.Run(name, func(t *testing.T) {
			_, err := fingerprint.KeyIDFromSPKI(der)
			if !errors.Is(err, fingerprint.ErrMalformed) {
				t.Fatalf("want ErrMalformed, got %v", err)
			}
		})
	}
}

var lowerHex64 = regexp.MustCompile(`^[0-9a-f]{64}$`)

func TestRenderings(t *testing.T) {
	c := fingerprint.CertFromDER([]byte("certificate"))
	if !lowerHex64.MatchString(c.Hex()) {
		t.Errorf("Hex %q is not 64 lowercase hex", c.Hex())
	}
	if c.String() != "sha256:"+c.Hex() {
		t.Errorf("String %q", c.String())
	}
	colon := c.Colon()
	if len(colon) != 95 || strings.ToUpper(c.Hex()) != strings.ReplaceAll(colon, ":", "") {
		t.Errorf("Colon %q is not the openssl-style rendering of %s", colon, c.Hex())
	}

	id, err := fingerprint.KeyIDFromSPKI(readFile(t, "testdata", "vectors", "ed25519", "spki.der"))
	if err != nil {
		t.Fatal(err)
	}
	enc := fingerprint.EncodedSPKIFromDER([]byte("spki"))

	for _, s := range []struct {
		got, want fingerprint.Scheme
	}{
		{c.Scheme(), "x509-cert-sha256"},
		{id.Scheme(), "x509-spki-sha256"},
		{enc.Scheme(), "x509-spki-encoded-sha256"},
	} {
		if s.got != s.want {
			t.Errorf("scheme %q, want %q", s.got, s.want)
		}
	}
	if (fingerprint.KeyID{}).IsZero() != true || id.IsZero() {
		t.Errorf("IsZero")
	}
}
